description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa ba biển báo cấm thuộc nhóm biển báo cấm theo QCVN 41:2024/BGTVT, bao gồm biển cấm đi ngược chiều (P.102), biển cấm xe ôtô (P.103a) và biển cấm xe ôtô rẽ phải (P.103b), kèm theo bản vẽ kỹ thuật kích thước hình học tương ứng.",
  "items": [
    {
      "identifier": "P.102",
      "visual_or_geometric_features": "Biển hình tròn, viền đỏ, nền trắng, biểu tượng mũi tên đen chỉ hướng đi ngược chiều bị gạch chéo đỏ. Bản vẽ kỹ thuật kèm theo có kích thước: đường kính biển 600mm, chiều cao mũi tên 300mm, độ dày gạch chéo 100mm.",
      "meaning_or_specification": "Biển báo cấm đi ngược chiều – cấm phương tiện đi theo hướng ngược với chiều cho phép của đường."
    },
    {
      "identifier": "P.103a",
      "visual_or_geometric_features": "Biển hình tròn, viền đỏ, nền trắng, biểu tượng hình xe ôtô đen bị gạch chéo đỏ. Bản vẽ kỹ thuật kèm theo có kích thước: đường kính biển 600mm, chiều cao xe ôtô 300mm, độ dày gạch chéo 100mm.",
      "meaning_or_specification": "Biển báo cấm xe ôtô – cấm tất cả các loại xe ôtô lưu thông trên đoạn đường này."
    },
    {
      "identifier": "P.103b",
      "visual_or_geometric_features": "Biển hình tròn, viền đỏ, nền trắng, biểu tượng hình xe ôtô đen đang rẽ phải bị gạch chéo đỏ. Bản vẽ kỹ thuật kèm theo có kích thước: đường kính biển 600mm, chiều cao xe ôtô 300mm, độ dày gạch chéo 100mm.",
      "meaning_or_specification": "Biển báo cấm xe ôtô rẽ phải – cấm xe ôtô thực hiện hành động rẽ phải tại vị trí biển báo."
    }
  ]
